-- Linha de base: tabelas criadas antes do versionamento (existiam só no banco ao vivo). Idempotente.
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname='app_role') THEN CREATE TYPE public.app_role AS ENUM ('admin', 'corretor', 'financeiro', 'diretor', 'gerente', 'administrativo'); END IF; END $$;
CREATE TABLE IF NOT EXISTS public.equipes (id uuid DEFAULT gen_random_uuid() NOT NULL, nome text NOT NULL, gestor_user_id uuid, ativo boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS public.corretores (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid, nome text NOT NULL, comissao_percentual numeric(5,2) DEFAULT 50 NOT NULL, ativo boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, email text, equipe_id uuid);
CREATE TABLE IF NOT EXISTS public.corretor_perfil_notas (id uuid DEFAULT gen_random_uuid() NOT NULL, corretor_id uuid NOT NULL, observacoes text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS public.corretor_perfis (id uuid DEFAULT gen_random_uuid() NOT NULL, corretor_id uuid NOT NULL, data_nascimento date, telefone_pessoal text, email_pessoal text, creci text, foto_url text, disc_dominancia integer, disc_influencia integer, disc_estabilidade integer, disc_conformidade integer, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS public.despesas (id uuid DEFAULT gen_random_uuid() NOT NULL, categoria text NOT NULL, descricao text, valor numeric(15,2) NOT NULL, mes integer NOT NULL, ano integer NOT NULL, tipo text DEFAULT 'empresa'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS public.empreendimentos (id uuid DEFAULT gen_random_uuid() NOT NULL, nome text NOT NULL, descricao text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, tipo text DEFAULT 'lancamento'::text NOT NULL, rua text, numero text, complemento text, condominio text, bairro text, cidade text);
CREATE TABLE IF NOT EXISTS public.captacoes (id uuid DEFAULT gen_random_uuid() NOT NULL, empreendimento_id uuid, corretor_id uuid, data_captacao date DEFAULT CURRENT_DATE NOT NULL, endereco text, observacao text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS public.user_roles (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, role app_role NOT NULL);
CREATE TABLE IF NOT EXISTS public.corretor_documentos (id uuid DEFAULT gen_random_uuid() NOT NULL, corretor_id uuid NOT NULL, cpf text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='user_roles_pkey' AND conrelid='public.user_roles'::regclass) THEN ALTER TABLE public.user_roles ADD CONSTRAINT user_roles_pkey PRIMARY KEY (id); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='corretor_documentos_pkey' AND conrelid='public.corretor_documentos'::regclass) THEN ALTER TABLE public.corretor_documentos ADD CONSTRAINT corretor_documentos_pkey PRIMARY KEY (id); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='corretor_perfis_pkey' AND conrelid='public.corretor_perfis'::regclass) THEN ALTER TABLE public.corretor_perfis ADD CONSTRAINT corretor_perfis_pkey PRIMARY KEY (id); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='captacoes_pkey' AND conrelid='public.captacoes'::regclass) THEN ALTER TABLE public.captacoes ADD CONSTRAINT captacoes_pkey PRIMARY KEY (id); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='equipes_pkey' AND conrelid='public.equipes'::regclass) THEN ALTER TABLE public.equipes ADD CONSTRAINT equipes_pkey PRIMARY KEY (id); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='corretor_perfil_notas_pkey' AND conrelid='public.corretor_perfil_notas'::regclass) THEN ALTER TABLE public.corretor_perfil_notas ADD CONSTRAINT corretor_perfil_notas_pkey PRIMARY KEY (id); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='corretores_pkey' AND conrelid='public.corretores'::regclass) THEN ALTER TABLE public.corretores ADD CONSTRAINT corretores_pkey PRIMARY KEY (id); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='despesas_pkey' AND conrelid='public.despesas'::regclass) THEN ALTER TABLE public.despesas ADD CONSTRAINT despesas_pkey PRIMARY KEY (id); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='empreendimentos_pkey' AND conrelid='public.empreendimentos'::regclass) THEN ALTER TABLE public.empreendimentos ADD CONSTRAINT empreendimentos_pkey PRIMARY KEY (id); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='user_roles_user_id_role_key' AND conrelid='public.user_roles'::regclass) THEN ALTER TABLE public.user_roles ADD CONSTRAINT user_roles_user_id_role_key UNIQUE (user_id, role); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='corretor_perfil_notas_corretor_id_key' AND conrelid='public.corretor_perfil_notas'::regclass) THEN ALTER TABLE public.corretor_perfil_notas ADD CONSTRAINT corretor_perfil_notas_corretor_id_key UNIQUE (corretor_id); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='corretor_documentos_corretor_id_key' AND conrelid='public.corretor_documentos'::regclass) THEN ALTER TABLE public.corretor_documentos ADD CONSTRAINT corretor_documentos_corretor_id_key UNIQUE (corretor_id); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='empreendimentos_tipo_check' AND conrelid='public.empreendimentos'::regclass) THEN ALTER TABLE public.empreendimentos ADD CONSTRAINT empreendimentos_tipo_check CHECK ((tipo = ANY (ARRAY['pronto'::text, 'lancamento'::text, 'estoque'::text, 'mcmv'::text]))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='despesas_mes_check' AND conrelid='public.despesas'::regclass) THEN ALTER TABLE public.despesas ADD CONSTRAINT despesas_mes_check CHECK (((mes >= 1) AND (mes <= 12))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='corretor_perfis_corretor_id_key' AND conrelid='public.corretor_perfis'::regclass) THEN ALTER TABLE public.corretor_perfis ADD CONSTRAINT corretor_perfis_corretor_id_key UNIQUE (corretor_id); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='despesas_tipo_check' AND conrelid='public.despesas'::regclass) THEN ALTER TABLE public.despesas ADD CONSTRAINT despesas_tipo_check CHECK ((tipo = ANY (ARRAY['empresa'::text, 'pessoal'::text]))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='corretor_perfis_corretor_id_fkey' AND conrelid='public.corretor_perfis'::regclass) THEN ALTER TABLE public.corretor_perfis ADD CONSTRAINT corretor_perfis_corretor_id_fkey FOREIGN KEY (corretor_id) REFERENCES corretores(id) ON DELETE CASCADE; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='user_roles_user_id_fkey' AND conrelid='public.user_roles'::regclass) THEN ALTER TABLE public.user_roles ADD CONSTRAINT user_roles_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='captacoes_empreendimento_id_fkey' AND conrelid='public.captacoes'::regclass) THEN ALTER TABLE public.captacoes ADD CONSTRAINT captacoes_empreendimento_id_fkey FOREIGN KEY (empreendimento_id) REFERENCES empreendimentos(id); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='corretores_user_id_fkey' AND conrelid='public.corretores'::regclass) THEN ALTER TABLE public.corretores ADD CONSTRAINT corretores_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='corretor_perfil_notas_corretor_id_fkey' AND conrelid='public.corretor_perfil_notas'::regclass) THEN ALTER TABLE public.corretor_perfil_notas ADD CONSTRAINT corretor_perfil_notas_corretor_id_fkey FOREIGN KEY (corretor_id) REFERENCES corretores(id) ON DELETE CASCADE; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='captacoes_corretor_id_fkey' AND conrelid='public.captacoes'::regclass) THEN ALTER TABLE public.captacoes ADD CONSTRAINT captacoes_corretor_id_fkey FOREIGN KEY (corretor_id) REFERENCES corretores(id); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='corretor_documentos_corretor_id_fkey' AND conrelid='public.corretor_documentos'::regclass) THEN ALTER TABLE public.corretor_documentos ADD CONSTRAINT corretor_documentos_corretor_id_fkey FOREIGN KEY (corretor_id) REFERENCES corretores(id) ON DELETE CASCADE; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='corretores_equipe_id_fkey' AND conrelid='public.corretores'::regclass) THEN ALTER TABLE public.corretores ADD CONSTRAINT corretores_equipe_id_fkey FOREIGN KEY (equipe_id) REFERENCES equipes(id) ON DELETE SET NULL; END IF; END $$;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.user_roles, public.corretor_documentos, public.corretor_perfis, public.captacoes, public.equipes, public.corretor_perfil_notas, public.corretores, public.despesas, public.empreendimentos TO authenticated;
GRANT ALL ON public.user_roles, public.corretor_documentos, public.corretor_perfis, public.captacoes, public.equipes, public.corretor_perfil_notas, public.corretores, public.despesas, public.empreendimentos TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.corretor_documentos ENABLE ROW LEVEL SECURITY;
