DO $p$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='user_roles' AND policyname='Diretores manage user_roles') THEN CREATE POLICY "Diretores manage user_roles" ON public.user_roles AS PERMISSIVE FOR ALL TO authenticated USING (has_role(auth.uid(), 'diretor'::app_role)) WITH CHECK (has_role(auth.uid(), 'diretor'::app_role)); END IF; END $p$;
DO $p$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='user_roles' AND policyname='Users view own roles or diretor views all') THEN CREATE POLICY "Users view own roles or diretor views all" ON public.user_roles AS PERMISSIVE FOR SELECT TO authenticated USING (((user_id = auth.uid()) OR has_role(auth.uid(), 'diretor'::app_role))); END IF; END $p$;
