DO $p$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='despesas' AND policyname='despesas_write') THEN CREATE POLICY despesas_write ON public.despesas AS PERMISSIVE FOR ALL TO authenticated USING ((is_diretor_or_gerente() OR has_permission('financeiro.gerenciar'::text))) WITH CHECK ((is_diretor_or_gerente() OR has_permission('financeiro.gerenciar'::text))); END IF; END $p$;
DO $p$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='empreendimentos' AND policyname='Users with a role view empreendimentos') THEN CREATE POLICY "Users with a role view empreendimentos" ON public.empreendimentos AS PERMISSIVE FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1 FROM user_roles ur WHERE (ur.user_id = auth.uid())))); END IF; END $p$;
DO $p$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='empreendimentos' AND policyname='empreendimentos_write') THEN CREATE POLICY empreendimentos_write ON public.empreendimentos AS PERMISSIVE FOR ALL TO authenticated USING ((is_diretor_or_gerente() OR has_permission('empreendimentos.gerenciar'::text))) WITH CHECK ((is_diretor_or_gerente() OR has_permission('empreendimentos.gerenciar'::text))); END IF; END $p$;
